 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;

  const { Group, Mesh, PlaneGeometry, RepeatWrapping, ClampToEdgeWrapping, SRGBColorSpace, DoubleSide, LinearFilter } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const group = new Group();

  const atlas = config.atlasRegion ?? { atlas: 0, sourceRect: [0, 0, 512, 320] };
  const [sx, sy, sw, sh] = atlas.sourceRect ?? [0, 0, 512, 320];
  const aspect = sw / sh || 1.6;

  const height = 2.0;
  const width = height * aspect;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
    color: colors.paper
  });

  const mesh = new Mesh(geometry, material);
  mesh.name = 'journal-card-2-sprite';
  group.add(mesh);

  mesh.onBeforeRender = function(_renderer, _scene, camera) {
    mesh.quaternion.copy(camera.quaternion);
  };

  group.userData.handlers = {};

  const timelines = [];

  if (config.cinematicPrimitives) {
    for (const primitive of config.cinematicPrimitives) {
      if (!ctx.primitives || !ctx.primitives[primitive.name]) continue;
      const result = ctx.primitives[primitive.name](group, primitive.params);
      if (result && result.timeline) timelines.push(result.timeline);
    }
  }

  const texUrl = config.imageUrl;
  if (texUrl) {
    ctx.textureLoader.loadTexture(texUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      tex.wrapS = ClampToEdgeWrapping;
      tex.wrapT = ClampToEdgeWrapping;
      tex.minFilter = LinearFilter;
      tex.magFilter = LinearFilter;

      const imgW = tex.image ? tex.image.width : sw;
      const imgH = tex.image ? tex.image.height : sh;

      tex.repeat.set(sw / Math.max(imgW, 1), sh / Math.max(imgH, 1));
      tex.offset.set(sx / Math.max(imgW, 1), sy / Math.max(imgH, 1));

      material.map = texture(tex);
      material.needsUpdate = true;
    });
  }

  group.userData.cleanup = function() {
    timelines.forEach((tl) => {
      if (tl && typeof tl.kill === 'function') tl.kill();
    });
    geometry.dispose();
    material.dispose();
    if (material.map && material.map.value && material.map.value.dispose) {
      material.map.value.dispose();
    }
  };

  return group;
}
